mapper.select:
SELECT ,s.bank as bankName,s.bank_acc as bankAcount,s.drawer as drawer,s.payee as payee,s.reviewer as reviewer,
(SELECT u.user_name from sys_user u where u.user_id = c.manager_accounting_user_id  ) manager_accounting ,
(SELECT u.user_name from sys_user u where u.user_id = c.bookkeeping_accounting_user_id  ) bookkeeping_accounting ,
(SELECT u.user_name from sys_user u where u.user_id = c.assistant_accounting_user_id  ) assistant_accounting
FROM t_customer c left join t_seller s on c.id = s.customer_id where c.del_flag = '0'

    and c.customer_name LIKE CONCAT('%',#{customerName},'%')


    and c.status = #{status}


    and c.dept_id = #{deptId}


    and c.manager_accounting_user_id = #{managerAccountingUserId}


    and c.bookkeeping_accounting_user_id = #{bookkeepingAccountingUserId}


    and c.assistant_accounting_user_id = #{assistantAccountingUserId}


    and c.is_open_invoice = #{isOpenInvoice}

order by c.create_time desc
